import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"46、【升】 巽下坤上","description":"周易口诀义 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"周易口诀义 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"zh/classics/koujueyi/048.md","filePath":"zh/classics/koujueyi/048.md"}'),r={name:"zh/classics/koujueyi/048.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><p>彖曰：柔以时升，巽而顺，刚中而应，是以大亨。「用见大人勿恤」，有庆也。「南征吉」，志行也。</p><p>象曰：地中生木，「升」，君子以顺德，积小以成高大。</p><p>初六：允升，大吉。</p><p>象曰：「允升大吉」，上合志也。</p><p>九二：孚乃利用礿，无咎。</p><p>象曰：九二之「孚」，有喜也。</p><p>九三，升虚邑。</p><p>象曰：「升虚邑」，无所疑也。</p><p>六四：王用亨于岐山，吉，无咎。</p><p>象曰：「王用亨于岐山」，顺事也。</p><p>六五：贞吉，升阶。</p><p>象曰：「贞吉升阶」，大得志也。</p><p>上六：冥升，利于不息之贞。</p><p>象曰：「冥升」在上，消不富也。</p><p>解读</p><p>「升元亨」者，升者渐进之名，登升之义，计必大通，故曰「元亨」。褚氏云：「犹人日思善道，进而不已，其德日新，故能亨也。」「用见大人，勿恤」者，刚不居中，无以统御于下，故须用见德大之人，然后无复忧恤也。「南征吉」者，南是阳明之方，当升之时，若往阴方，即弥加暗昧。既见德大之人，复宜适阳明之方，即升进之道通矣。二方以喻人之明昧也。象曰「地中生木，升」者，升是渐渐登升道长之义，亦犹地中生木，从下升高，自微至著也。「君子以顺德，积小以成高大」者，孔义云：「君子象之，所以顺行其德，积其小善，以成高大。」又何妥云：「君子谨习为先，修习道德，积其微小，以至高大。」案：此之义，「顺」字恐当为「慎」也。</p><p>「初六允升，大吉」者，允，当也；二三皆有应于上，故升之不疑。唯初六上无其应，体又柔劣，不能自进，当九二、九三升进之时，与之俱行，上合志，必大得矣，故曰「允升，大吉」，亦犹九二、九三「许允」，即获吉也。</p><p>九二「孚乃利用礿，无咎」者，九二与五为应，九二前进，五必信任，故曰「有孚」也。二体刚中，诚乎信实，进不求宠，志弘大业，直是享荐神明，但可俭约薄省而己，亦得喜庆臻至，更有何咎？故「利用礿，无咎」，盖为上应于君矣。</p><p>「九三升虚邑」者，以刚得位，己以进前，上体应柔，不拒于己，若升其虚邑，无所疑滞，故小象云「无所疑」也。</p><p>六四「王用亨于岐山，吉，无咎」者，体柔居四，下体三爻皆悉上升，处升之际，可纳而不可拒，其犹太王避狄之难，居岐山之会，故曰「王用亨于岐山」也。若能因物而成，顺事之情，纳而不拒，所以得「吉」而「无咎」，故曰「吉，无咎」也。</p><p>六五「贞吉，升阶」者，以柔居尊，不自专制，委任九二，任用得人，故得保其升阶而践贵位也。</p><p>「上六冥升，利于不息之贞」者，冥犹瞑也。既处升极而更升进，即是瞑暗不得明了，而犹求升，故曰「冥升」。若冥然求升，欲为物之主者，即丧亡交至，如克己修身而不暂息，施于正即利莫大焉，故曰「利于不息之贞」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
